// Generated by scripts/build-bank.mjs from docs/rules and docs/shapes.
// Edit those files, not this one.

export type Family = 'common' | 'fable' | 'opus' | 'sonnet' | 'haiku'
export type Rule = { id: string; text: string }
export type Shape = { name: string; summary: string; fields: string; context: string; before: string; after: string }

export const RULES: Record<Family, readonly Rule[]> = {
  "common": [
    {
      "id": "keep-intent",
      "text": "Keep what the user asked for. Do not add tasks, change the goal, or answer the prompt yourself. Resolve references to the conversation (\"the second item above\", \"that file\", \"same as before\") into the concrete names they point to, and invent nothing the conversation does not show: no file names, numbers, deadlines or requirements. Keep the user's own uncertainty (\"I guess\", \"maybe\") where they wrote it, and never add guesses of your own."
    },
    {
      "id": "give-the-reason",
      "text": "When the conversation or the prompt shows why the user wants this or who it is for, say it in one plain sentence. If the reason is not knowable, leave it out rather than guess."
    },
    {
      "id": "name-the-deliverable",
      "text": "Make the output explicit: what should exist or be answered when Claude is done, and how the user will tell it is done (tests pass, a file exists, a question answered). Use a check that already exists (the tests, a command) as the done signal; do not add work the user did not ask for, such as new tests. Use a short numbered list only when the order of steps matters."
    },
    {
      "id": "question-stays-a-question",
      "text": "If the user is asking a question, describing a problem or thinking out loud, the rewrite asks for an assessment and says not to change anything yet. Never turn a question into an order to fix."
    },
    {
      "id": "state-what-is-out",
      "text": "When the prompt or conversation makes clear what must not be touched, say it in one sentence (files, behaviour, scope). Do not invent restrictions."
    },
    {
      "id": "ideas-mean-ideas",
      "text": "If the user asks for ideas, options or a plan, the rewrite asks for that and says to wait before building anything."
    },
    {
      "id": "no-reasoning-echo",
      "text": "Never ask Claude to show, write out or explain its thinking or reasoning, and never add \"think step by step\". Recent models may refuse such requests (the reasoning_extraction category). Asking for a short explanation of the answer is fine."
    },
    {
      "id": "calm-language",
      "text": "No capital-letter emphasis, no \"CRITICAL\" or \"MUST\", no threats or bribes, no urgency. Current models follow plain instructions and over-apply shouted ones."
    },
    {
      "id": "no-role-filler",
      "text": "Do not open with a role (\"You are an expert ...\"). The prompt is a user turn inside Claude Code, which already has its system prompt; a role line there only adds length."
    },
    {
      "id": "stay-short",
      "text": "The rewrite is at most twice the length of the original or 60 words, whichever is more, and never more than 180 words. Write it in the user's language and voice (or in English when the rewriteLanguage setting says en), first person, as if they had typed it carefully. No headings, no XML tags, no preamble."
    },
    {
      "id": "latest-reference",
      "text": "When a reference in the draft (\"that function\", \"the file\", \"the test\") fits more than one thing in the conversation, take the most recent one and name it, with its file when there is one."
    }
  ],
  "fable": [
    {
      "id": "fable-brief-is-enough",
      "text": "Prefer one short instruction over a list of cases. Fable follows brief instructions well and over-prescriptive prompts can make its output worse."
    },
    {
      "id": "fable-ask-for-updates",
      "text": "If the task is long and the user wants to follow along, ask for a line before starting and a short recap at the end. Fable 5.1 writes few updates between tool calls unless asked. Do not ask it to keep updates brief."
    },
    {
      "id": "fable-ambiguity",
      "text": "Where the request can be read two ways and the conversation does not settle it, ask Claude to take the most direct reading and state that assumption, rather than build for both."
    },
    {
      "id": "fable-bug-phrasing",
      "text": "Turn \"does this compile?\" into \"are there any bugs in this?\". The compile-check phrasing trips safety classifiers more often."
    }
  ],
  "opus": [
    {
      "id": "opus-no-verify-step",
      "text": "Do not add \"verify your work\" or \"add a final verification step\". Opus 5 verifies on its own and extra verification instructions waste tokens."
    },
    {
      "id": "opus-hold-scope",
      "text": "For a narrow task, say plainly to deliver what was asked at that scope and to mention, not do, anything beyond it. Opus 5 can widen a task on its own."
    },
    {
      "id": "opus-length",
      "text": "If the user wants a document or reply of a certain size, say so. Opus 5 writes longer replies and documents by default, and effort does not reliably shorten them."
    }
  ],
  "sonnet": [
    {
      "id": "sonnet-literal-scope",
      "text": "Spell out how far an instruction reaches (\"every file under src/, not just this one\"). Sonnet 5 reads prompts literally and does not generalise an instruction from one item to the rest."
    },
    {
      "id": "sonnet-no-extras",
      "text": "When the user wants only the change itself, say not to add tests, docs or files that were not asked for. Sonnet 5.5 tends to add them."
    }
  ],
  "haiku": [
    {
      "id": "haiku-run-a-check",
      "text": "For a code change that can be run, built or type-checked, ask for a real check (the tests, the type-checker, the build) before calling it done. Haiku 5.5 at low effort sometimes reports a change as done without checking it."
    }
  ]
}

