{
  "name": "sharpprompt",
  "version": "0.2.0",
  "description": "Lets clear prompts through untouched and rewrites rough ones into the prompt box for you to check before sending.",
  "author": {
    "name": "Onderhan Islekoglu",
    "url": "https://github.com/ondrhn"
  },
  "homepage": "https://github.com/ondrhn/sharpprompt",
  "repository": "https://github.com/ondrhn/sharpprompt",
  "license": "MIT",
  "keywords": [
    "prompt",
    "rewrite",
    "mods"
  ],
  "types": "./types/index.d.ts",
  "userConfig": {
    "mode": {
      "type": "string",
      "title": "Mode",
      "description": "fill puts the rewrite in the prompt box, replace sends it, context adds a hint, off does nothing",
      "default": "fill",
      "options": [
        "fill",
        "replace",
        "context",
        "off"
      ]
    },
    "optimizerModel": {
      "type": "string",
      "title": "Helper model",
      "description": "Model for the rough-or-clear check and for the fallback rewrite when there is no conversation yet. The usual rewrite runs on the session model, because it reads the conversation from the cache",
      "default": "haiku",
      "options": [
        "haiku",
        "sonnet"
      ]
    },
    "minChars": {
      "type": "number",
      "title": "Minimum length",
      "description": "Prompts shorter than this pass through untouched",
      "default": 40
    },
    "rewriteLanguage": {
      "type": "string",
      "title": "Rewrite language",
      "description": "same keeps the language you wrote in; en always rewrites into English",
      "default": "same",
      "options": [
        "same",
        "en"
      ]
    },
    "askBeforeSend": {
      "type": "boolean",
      "title": "Ask before sending",
      "description": "When a rough prompt leaves out something the conversation does not answer, ask up to three questions in one dialog before the rewrite goes in the box",
      "default": true
    },
    "sessionFacts": {
      "type": "boolean",
      "title": "Session facts",
      "description": "Give the rewriter the files this session read or changed and the last failed command, from the transcript only",
      "default": true
    },
    "log": {
      "type": "boolean",
      "title": "Usage log",
      "description": "Keep each rewrite's draft, rewrite, questions and what you did with it (last 300), for /sharp stats and scripts/export_log.mjs. Stays on your machine",
      "default": true
    }
  }
}

files.types/index.d.ts:
export type SharppromptMode = 'fill' | 'replace' | 'context' | 'off'

// Why the cheap gate let a prompt through untouched. 'suggested' is a prompt
// sent while our suggestion was in the box: the user's answer to it.
export type SharppromptSkip =
  | 'off'
  | 'not-typed'
  | 'raw'
  | 'command'
  | 'heading'
  | 'too-short'
  | 'too-long'
  | 'harness-tag'
  | 'answer'
  | 'suggested'
  | 'back-to-mine'

// What the classifier said; 'timeout' and 'error' send the prompt as typed.
export type SharppromptVerdict = 'clear' | 'rough' | 'timeout' | 'error'

// How a rewrite went. Only 'rewritten' carries text; every other outcome
// sends the prompt as typed.
export type SharppromptQuestion = { question: string; header: string; options: { label: string; adds: string }[] }

export type SharppromptRewrite = {
  outcome: 'rewritten' | 'keep' | 'same' | 'empty' | 'too-long' | 'timeout' | 'error'
  via: 'fork' | 'complete'
  ms: number
  text?: string
  detail?: string
  // Gaps the rewriter wanted to ask about; their answers are added to text.
  questions?: SharppromptQuestion[]
  usage?: { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }
}

export type SharppromptDecision =
  | { verdict: 'skip'; reason: SharppromptSkip; text: string }
  | { verdict: SharppromptVerdict; text: string; classifyMs?: number; rewrite?: SharppromptRewrite }

// A rewrite the user has not acted on yet: in the box (filled) or already
// sent (replaced), shown in the band; or the user's own text put back in the
// box (restored), which goes out untouched if sent as it stands.
export type SharppromptPending = {
  kind: 'filled' | 'replaced' | 'restored'
  original: string
  rewritten: string
  // The usage-log record of this rewrite, when the log is on.
  log?: string
}

declare module 'claude-code' {
  interface PluginState {
    sharpprompt: {
      pending: SharppromptPending | null
      isOff: boolean
      mode: SharppromptMode | null
      lastDecision: SharppromptDecision | null
    }
  }
}
